function bfParse(text){
  return String(text).split(/[\s,]+/).map(Number).filter(function(x){ return isFinite(x); });
}
function bfMean(xs){
  var s=0; for(var i=0;i<xs.length;i++) s+=xs[i];
  return s/xs.length;
}
function bfMedian(xs){
  var a=xs.slice().sort(function(p,q){ return p-q; });
  var mid=a.length>>1;
  return a.length%2 ? a[mid] : (a[mid-1]+a[mid])/2;
}
function bfStddev(xs){
  if(xs.length<2) return 0;
  var m=bfMean(xs), s=0;
  for(var i=0;i<xs.length;i++) s+=(xs[i]-m)*(xs[i]-m);
  return Math.sqrt(s/(xs.length-1));
}
function bfMad(xs){
  var med=bfMedian(xs);
  return bfMedian(xs.map(function(x){ return Math.abs(x-med); }));
}
function bfStats(xs){
  if(!xs||xs.length===0) return { value:null, error:'样本为空' };
  var a=xs.slice().sort(function(p,q){ return p-q; });
  return { value:{ n:xs.length, mean:bfMean(xs), median:bfMedian(xs), stddev:bfStddev(xs),
    mad:bfMad(xs), min:a[0], max:a[a.length-1],
    p95:a[Math.min(a.length-1, Math.ceil(a.length*0.95)-1)] }, error:null };
}
function bfOutliers(xs){
  if(!xs||xs.length<3) return { value:{ outliers:[], indexes:[] }, error:null };
  var med=bfMedian(xs), mad=bfMad(xs), out=[], idx=[];
  for(var i=0;i<xs.length;i++){
    var bad;
    if(mad===0) bad = xs[i]!==med;
    else bad = Math.abs(0.6745*(xs[i]-med)/mad) > 3.5;
    if(bad){ out.push(xs[i]); idx.push(i); }
  }
  return { value:{ outliers:out, indexes:idx }, error:null };
}
function bfCompare(a, b){
  var sa=bfStats(a), sb=bfStats(b);
  if(sa.error||sb.error) return { value:null, error:sa.error||sb.error };
  var A=sa.value, B=sb.value;
  if(A.mean<=0||B.mean<=0) return { value:null, error:'均值必须为正' };
  var fast = A.mean<=B.mean ? 'A' : 'B';
  var ratio = A.mean<=B.mean ? B.mean/A.mean : A.mean/B.mean;
  var relErr = Math.sqrt(Math.pow(A.stddev/A.mean,2)+Math.pow(B.stddev/B.mean,2));
  return { value:{ faster:fast, ratio:ratio, ratioErr:ratio*relErr, meanA:A.mean, meanB:B.mean }, error:null };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { bfParse:bfParse, bfMean:bfMean, bfMedian:bfMedian, bfStddev:bfStddev,
    bfMad:bfMad, bfStats:bfStats, bfOutliers:bfOutliers, bfCompare:bfCompare };
}
if (typeof window !== 'undefined') {
  window.BenchForgePure = { bfParse:bfParse, bfMean:bfMean, bfMedian:bfMedian, bfStddev:bfStddev,
    bfMad:bfMad, bfStats:bfStats, bfOutliers:bfOutliers, bfCompare:bfCompare };
}
